// edit time on the older stored body, so importers would skip its next publish. Node
// concepts hold no other slot, so the whole reference_content is replaced.
const restoreSourceReferences = async ({
  client,
  spaceId,
  sources,
  discourseNodes,
}: {
  client: DGSupabaseClient;
  spaceId: number;
  sources: PublishedSource[];
  discourseNodes: DiscourseNode[];
}): Promise<void> => {
  if (sources.length === 0) return;
  const dependentsBySourceUid = new Map<
    string,
    { conceptId: number; dependentUids: string[] }
  >(
    sources.map(({ uid, conceptId }) => [
      uid,
      { conceptId, dependentUids: [] },
    ]),
  );
  const titlesByUid = await pagesWithTitleContaining(
    sources.map(({ title }) => title),
  );
  for (const [uid, title] of titlesByUid) {
    const nodeType = findDiscourseNode({ uid, title, nodes: discourseNodes });
    if (!nodeType) continue;
    const sourceId = sourceIdOfNode(title, nodeType, discourseNodes);
    if (sourceId !== undefined)
      dependentsBySourceUid.get(sourceId)?.dependentUids.push(uid);
  }
  for (const { conceptId, dependentUids } of dependentsBySourceUid.values()) {
    if (dependentUids.length === 0) continue;
    const { error } = await client
      .from("Concept")
      .update({ reference_content: { [SOURCE_SLOT]: conceptId } })
      .eq("space_id", spaceId)
      .in("source_local_id", dependentUids)
      .is(`reference_content->>${SOURCE_SLOT}`, null);
    if (error) throw error;
  }
};

type PublishNodesResult = {
  publishedNodeSchemaUids: string[];
  publishedNodeUids: string[];
  publishedRelationTripleSchemaUids: string[];
  publishedRelationUids: string[];
  syncedNodeSchemaUids: string[];
----
import getDiscourseNodes, { type DiscourseNode } from "./getDiscourseNodes";
import matchDiscourseNode from "./matchDiscourseNode";
import type { SettingsSnapshot } from "~/components/settings/utils/accessors";
import { getDiscourseNodeTypeCacheVersion } from "./discourseNodeTypeCache";

let discourseNodeTypeCache: Record<string, DiscourseNode | false> = {};
let discourseNodeTypeCacheVersion = -1;

const findDiscourseNode = ({
  uid,
  title,
  nodes,
  snapshot,
}: {
  uid: string;
  title?: string;
  nodes?: DiscourseNode[];
  snapshot?: SettingsSnapshot;
}): DiscourseNode | false => {
  const currentCacheVersion = getDiscourseNodeTypeCacheVersion();
  if (discourseNodeTypeCacheVersion !== currentCacheVersion) {
    discourseNodeTypeCache = {};
    discourseNodeTypeCacheVersion = currentCacheVersion;
  }

  if (typeof discourseNodeTypeCache[uid] !== "undefined") {
    return discourseNodeTypeCache[uid];
  }

  const resolvedNodes = nodes ?? getDiscourseNodes(snapshot);
  const matchingNode =
    resolvedNodes.find((node) =>
      title === undefined
        ? matchDiscourseNode({ ...node, uid })
        : matchDiscourseNode({ ...node, title }),
    ) || false;
  discourseNodeTypeCache[uid] = matchingNode;
  return matchingNode;
};
export default findDiscourseNode;

