{
  "why": "open DG: Discover shared nodes",
  "steps": [
    {
      "do": {
        "command_palette": "DG: Discover shared nodes"
      },
      "why": "open import the way a user would"
    },
    {
      "do": {
        "wait_for": ".bp3-dialog:visible"
      },
      "why": "wait for the import dialog"
    }
  ]
}
{
  "id": "roam-prediction",
  "why": "the dev graph published a PK Prediction node type with a template, and one node, to the same group",
  "phase": "outside",
  "apply": {
    "publish": {
      "space": 66566,
      "author": 3,
      "group": "eng-2329-demo",
      "types": [
        {
          "id": "pk-2350-prediction",
          "label": "PK Prediction",
          "format": "[[PRD]] - {content}",
          "template": "- Expected result\n- How we will know"
        }
      ],
      "nodes": [
        {
          "id": "pk-2350-roam-prediction",
          "type": "pk-2350-prediction",
          "title": "Recall improves after a nap",
          "body": "- Measured the next morning."
        }
      ]
    }
  }
}
{
  "id": "no-earlier-import",
  "why": "neither node type nor node was imported into this graph before",
  "phase": "before-load",
  "check": {
    "js": "![\"discourse-graph/nodes/PK Hypothesis\", \"discourse-graph/nodes/PK Prediction\", \"HYP - Sleep spindles predict recall\", \"[[PRD]] - Recall improves after a nap\"].some((title) => proof.page.exists(title))"
  },
  "apply": {
    "js": "proof.page.remove([\"discourse-graph/nodes/PK Hypothesis\", \"discourse-graph/nodes/PK Prediction\", \"HYP - Sleep spindles predict recall\", \"[[PRD]] - Recall improves after a nap\"])"
  }
}
{
  "id": "obsidian-type-brings-its-template",
  "title": "Importing an Obsidian node creates its node type with the template",
  "checks": "PK Hypothesis exists, its Template has the Prediction and How to test it sections, and no frontmatter came across",
  "steps": [
    {
      "use": "discover.open",
      "why": "open import the way a user would"
    },
    {
      "do": {
        "wait_for": ".bp3-dialog tbody tr:has-text(\"Sleep spindles predict recall\")"
      },
      "why": "wait for the shared node's row"
    },
    {
      "do": {
        "click": ".bp3-dialog tbody tr:has-text(\"Sleep spindles predict recall\") label.bp3-checkbox"
      },
      "why": "select it"
    },
    {
      "do": {
        "click": ".bp3-dialog button:has-text(\"Import selected (1)\")"
      },
      "why": "import the selection"
    },
    {
      "do": {
        "wait_for": ".bp3-dialog .bp3-callout:has-text(\"imported\")"
      },
      "why": "wait for the import result"
    },
    {
      "do": {
        "pause": 1.5
      },
      "why": "hold on the result"
    }
  ],
  "expect": {
    "js": "proof.waitFor(() => { const lines = proof.nodeType.template('PK Hypothesis'); return lines && lines.some((line) => line.includes('Prediction')) && lines.some((line) => line.includes('smallest experiment')) && !lines.some((line) => /tags:|---/.test(line)); }, { what: \"PK Hypothesis's template, without its frontmatter\", timeout: 15000 })"
  }
}

